import {Field,AmountInput} from '@bloxwap/hig-native/field';
import {HIGProvider} from '@bloxwap/hig-native/provider';
import {Stack,Text} from '@bloxwap/hig-native/surface';

export default function Example(){
const [checked,setChecked]=useState(false),[value,setValue]=useState('buy'),[range,setRange]=useState(25),[open,setOpen]=useState(false),[amount,setAmount]=useState('0.01'),[message,setMessage]=useState('');
const [notices,setNotices]=useState([{id:'1',message:'Demo copied',severity:'success' as const}]);
const choices=[{value:'buy',label:'Buy'},{value:'sell',label:'Sell'}];const rows:{id:string;label:string;value:number}[]=[{id:'btc',label:'Bitcoin (BTC)',value:67234.56}];
const empty=false,busy=false,disabled=false,error=undefined;
return <HIGProvider density="comfortable"><Stack><Field label='Amount (BTC)' description='Raw decimal string; host validates precision' error={error}><AmountInput value={amount} onChangeText={setAmount} editable={!disabled}/></Field><Text>{message}</Text></Stack></HIGProvider>;
}

